import classNames from 'classnames';
import React from 'react';
import type {RefObject} from 'react';
import type {MessageDescriptor, IntlShape} from 'react-intl';
import {FormattedMessage, defineMessages, injectIntl} from 'react-intl';
import {components} from 'react-select';
import type {FormatOptionLabelMeta, InputActionMeta, InputProps, Options, StylesConfig, SelectInstance, MultiValue, SingleValue, OptionsOrGroups, GroupBase, MultiValueRemoveProps} from 'react-select';
import AsyncCreatable from 'react-select/async-creatable';

import type {UserProfile} from '@mattermost/types/users';

import {Client4} from 'mattermost-redux/client';
import {isEmail} from 'mattermost-redux/utils/helpers';
import {isGuest} from 'mattermost-redux/utils/user_utils';

import FormattedMarkdownMessage from 'components/formatted_markdown_message';
import CloseCircleSolidIcon from 'components/widgets/icons/close_circle_solid_icon';
import MailIcon from 'components/widgets/icons/mail_icon';
import MailPlusIcon from 'components/widgets/icons/mail_plus_icon';
import LoadingSpinner from 'components/widgets/loading/loading_spinner';
import BotTag from 'components/widgets/tag/bot_tag';
import GuestTag from 'components/widgets/tag/guest_tag';
import Avatar from 'components/widgets/users/avatar';

import {getDisplayName, getLongDisplayNameParts, imageURLForUser} from 'utils/utils';

import './users_emails_input.scss';

type Props = {
    placeholder: string;
    ariaLabel: string;
    usersLoader: (search: string, callback: (users: UserProfile[]) => void) => Promise<UserProfile[]> | undefined;
    onUsersLoad?: (users: UserProfile[]) => void;
    onChange: (change: Array<UserProfile | string>) => void;
    showError?: boolean;
    errorMessage?: MessageDescriptor;
    errorMessageValues?: Record<string, React.ReactNode>;
    value: Array<UserProfile | string>;
    onInputChange: (change: string) => void;
    inputValue: string;
    noMatchMessage?: MessageDescriptor;
    validAddressMessage?: MessageDescriptor;
    loadingMessage?: MessageDescriptor;
    emailInvitationsEnabled: boolean;
    extraErrorText?: React.ReactNode;
    autoFocus?: boolean;
    suppressNoOptionsMessage?: boolean;
    onPaste?: (e: ClipboardEvent) => void;
    intl: IntlShape;
};

export type EmailInvite = {
    value: string;
    label: string;
};

type State = {
    options: UserProfile[];
    prevValue: string;
};

const typedInputDelimiter = /[,;]+/;
const pasteDelimiter = /[\n\r,;]+/;
const spaceSeparatedPasteDelimiter = /\s+/;

type PasteHandling =
    {mode: 'draft'} |
    {mode: 'bulk'; delimiter: RegExp};

const getPasteHandling = (value: string): PasteHandling => {
    const trimmedValue = value.trim();
    if (!trimmedValue) {
        return {mode: 'draft'};
    }

    if (isEmail(trimmedValue)) {
        return {mode: 'bulk', delimiter: pasteDelimiter};
    }

    if ((/[,;\n\r]/).test(trimmedValue)) {
        return {mode: 'bulk', delimiter: pasteDelimiter};
    }

    const entries = trimmedValue.split(spaceSeparatedPasteDelimiter).map((entry) => entry.trim()).filter(Boolean);
    if (entries.length > 1 && entries.every((entry) => isEmail(entry))) {
        return {mode: 'bulk', delimiter: spaceSeparatedPasteDelimiter};
    }

    return {mode: 'draft'};
};

const isLikelyBulkPasteInput = (nextValue: string, previousValue: string): PasteHandling => {
    if (nextValue.length - previousValue.length <= 1) {
        return {mode: 'draft'};
    }

    return getPasteHandling(nextValue);
};

const messages = defineMessages({
    loadingDefault: {
        id: 'widgets.users_emails_input.loading',
        defaultMessage: 'Loading',
    },
    noMatchDefault: {
        id: 'widgets.users_emails_input.no_user_found_matching',
        defaultMessage: 'No one found matching **{text}**. Enter their email to invite them.',
    },
    validAddressDefault: {
        id: 'widgets.users_emails_input.valid_email',
        defaultMessage: 'Add **{email}**',
    },
});

export class UsersEmailsInput extends React.PureComponent<Props, State> {
    static defaultProps = {
        noMatchMessage: messages.noMatchDefault,
        validAddressMessage: messages.validAddressDefault,
        loadingMessage: messages.loadingDefault,
        showError: false,
    };
    private selectRef: RefObject<SelectInstance<UserProfile | EmailInvite, true>>;

    constructor(props: Props) {
        super(props);
        this.selectRef = React.createRef();
        this.state = {
            options: [],
            prevValue: this.props.inputValue,
        };
    }

    renderUserName = (user: UserProfile) => {
        const parts = getLongDisplayNameParts(user);
        let fullName = null;
        if (parts.fullName) {
            fullName = (<span className='fullname'>{parts.fullName}</span>);
        }
        let nickname = null;
        if (parts.nickname) {
            nickname = (<span className='nickname'>{parts.nickname}</span>);
        }

        return (
            <>
                {parts.displayName}
                {fullName}
                {nickname}
            </>
        );
    };

    loadingMessage = (): string => {
        const text = (
            <FormattedMessage
                {...this.props.loadingMessage}
            />
        );

        // faking types to satisfy the interface for the version of react-select we are on.
        return (<LoadingSpinner text={text}/>) as unknown as string;
    };

    getOptionValue = (obj: UserProfile | EmailInvite): string => {
        if (this.isUserProfile(obj)) {
            return obj.id;
        }
        return obj.value;
    };

    formatOptionLabel = (user: UserProfile | EmailInvite, options: FormatOptionLabelMeta<UserProfile | EmailInvite>) => {
        const profileImg = imageURLForUser((user as UserProfile).id, (user as UserProfile).last_picture_update);
        let guestBadge = null;
        let botBadge = null;

        if ((user as UserProfile).is_bot) {
            botBadge = <BotTag/>;
        }

        if (!isEmail((user as EmailInvite).value) && isGuest((user as UserProfile).roles)) {
            guestBadge = <GuestTag/>;
        }

        if (options.context === 'menu') {
            if ((user as EmailInvite).value && isEmail((user as EmailInvite).value)) {
                return this.getCreateLabel((user as EmailInvite).value);
            }
            return (
                <>
                    <Avatar
                        size='lg'
                        username={(user as UserProfile).username}
                        url={profileImg}
                    />
                    {this.renderUserName(user as UserProfile)}
                    {botBadge}
                    {guestBadge}
                </>
            );
        }

        if ((user as EmailInvite).value && isEmail((user as EmailInvite).value)) {
            return (
                <>
                    <MailIcon className='mail-icon'/>
                    <span>{(user as EmailInvite).value}</span>
                </>
            );
        }

        return (
            <>
                <Avatar
                    size='sm'
                    username={(user as UserProfile).username}
                    url={profileImg}
                />
                {getDisplayName(user as UserProfile)}
                {botBadge}
                {guestBadge}
            </>
        );
    };

    onChange = (value: MultiValue<EmailInvite | UserProfile> | SingleValue<EmailInvite | UserProfile>) => {
        if (this.props.onChange) {
            if (value) {
                this.props.onChange((value as Array<UserProfile | EmailInvite>).map((v) => {
                    if (this.isUserProfile(v)) {
                        return v;
                    }
                    return v.value;
                }));
            } else {
                this.props.onChange([]);
            }
        }
    };

    getCreateLabel = (value: string) => (
        <>
            <MailPlusIcon className='mail-plus-icon'/>
            <FormattedMarkdownMessage
                key='widgets.users_emails_input.valid_email'
                {...this.props.validAddressMessage}
                values={{email: value}}
                disableLinks={true}
            />
        </>
    );

    Input = (props: InputProps<EmailInvite | UserProfile, true>) => {
        const handlePaste = (e: ClipboardEvent) => {
            const clipboardText = e.clipboardData?.getData('Text') || '';
            const pasteHandling = getPasteHandling(clipboardText);
            if (pasteHandling.mode === 'bulk') {
                e.preventDefault();
                this.appendDelimitedValues(clipboardText, pasteHandling.delimiter).catch(() => undefined);
            }

            if (this.props.onPaste) {
                this.props.onPaste(e);
            }
        };

        return (
            <components.Input
                {...props}

                // The onPaste is not part of the InputProps type definition. It's fixed in v5 of react-select.
                // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                // @ts-ignore - The type definition for the Input component is incorrect.
                onPaste={handlePaste}
            />
        );
    };

    NoOptionsMessage = (props: Record<string, any>) => {
        const inputValue = props.selectProps.inputValue;
        if (!inputValue) {
            return null;
        }

        const Msg: any = components.NoOptionsMessage;
        return (
            <div className='users-emails-input__option users-emails-input__option--no-matches'>
                <Msg {...props}>
                    <FormattedMarkdownMessage
                        {...this.props.noMatchMessage}
                        values={{text: inputValue}}
                        disableLinks={true}
                    />
                </Msg>
            </div>
        );
    };

    private renderAriaLabel = (option: UserProfile | EmailInvite): string => {
        if (!option) {
            return '';
        }

        if (this.isUserProfile(option)) {
            return (option as UserProfile).username;
        }

        return (option as EmailInvite).value;
    };

    MultiValueRemove = (props: MultiValueRemoveProps<EmailInvite | UserProfile, true>) => {
        const {children, innerProps} = props;

        return (
            <div
                {...innerProps}
                role='button'
                tabIndex={0}
                aria-label={this.props.intl.formatMessage({
                    id: 'multiselect.remove',
                    defaultMessage: 'Remove {label}',
                }, {
                    label: this.renderAriaLabel(props.data),
                })}
                onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        e.stopPropagation();
                        innerProps.onClick?.(e as unknown as React.MouseEvent<HTMLDivElement, MouseEvent>);
                    }
                }}
            >
                {children || <CloseCircleSolidIcon/>}
            </div>
        );
    };

    components = {
        NoOptionsMessage: this.props.suppressNoOptionsMessage ? () => null : this.NoOptionsMessage,
        MultiValueRemove: this.MultiValueRemove,
        IndicatorsContainer: () => null,
        Input: this.Input,
    };

    handleInputChange = async (inputValue: string, action: InputActionMeta) => {
        if (action.action === 'input-blur' && action.prevInputValue !== '') {
            const values = this.formatValuesForCreatable();

            // Check if the input is an existing user by username or email.
            const option = this.state.options.find((o) =>
                action.prevInputValue === o.username || action.prevInputValue === ('@' + o.username) ||
                action.prevInputValue === o.email,
            );

            if (option) {
                this.onChange([...values, option]);
                this.props.onInputChange('');
                this.setState((state) => ({
                    ...state,
                    prevValue: action.prevInputValue,
                }));
                return;
            }

            // Check if the input is a valid new email, if the email invitations are enabled.
            if (this.props.emailInvitationsEnabled && isEmail(action.prevInputValue)) {
                const email = action.prevInputValue;
                this.onChange([...values, {value: email, label: email}]);
                this.props.onInputChange('');
                this.setState((state) => ({
                    ...state,
                    prevValue: action.prevInputValue,
                }));
            }
        } else if (action.action === 'input-change') {
            const likelyBulkPaste = isLikelyBulkPasteInput(inputValue, action.prevInputValue || '');
            if (likelyBulkPaste.mode === 'bulk') {
                const newValuesCount = await this.appendDelimitedValues(inputValue, likelyBulkPaste.delimiter);
                if (newValuesCount === 0) {
                    return;
                }
                return;
            }

            if (action.prevInputValue !== '' && action.prevInputValue?.[action.prevInputValue.length - 1].match(typedInputDelimiter)) {
                const newValuesCount = await this.appendDelimitedValues(action.prevInputValue, typedInputDelimiter);
                if (newValuesCount === 0) {
                    return;
                }
            }
        }
        if (action.action !== 'input-blur' && action.action !== 'menu-close') {
            this.props.onInputChange(inputValue);
            this.setState((state) => ({
                ...state,
                prevValue: action.prevInputValue,
            }));
        }
    };

    formatValuesForCreatable = () => {
        return this.props.value.map((v) => {
            if ((v as UserProfile).id) {
                return v as UserProfile;
            }
            return {label: v, value: v} as EmailInvite;
        });
    };

    optionsLoader = (inputValue: string, callback: (options: UserProfile[]) => void) => {
        const customCallback = (options: UserProfile[]) => {
            this.setState({options});
            const accessibleProfiles = options.map((user: UserProfile) => ({...user, label: user.username}));
            callback(accessibleProfiles);
            if (this.props.onUsersLoad) {
                this.props.onUsersLoad(options);
            }
        };
        const result = this.props.usersLoader(inputValue, customCallback);
        if (result && result.then) {
            result.then(customCallback);
        }
    };

    showAddEmail = (inputValue: string, value: Options<UserProfile | EmailInvite>, options: OptionsOrGroups<EmailInvite | UserProfile, GroupBase<EmailInvite | UserProfile>>): boolean => {
        return this.props.emailInvitationsEnabled && options.length === 0 && isEmail(inputValue);
    };

    onFocus = () => {
        this.selectRef.current?.onInputChange(this.props.inputValue, {action: 'set-value', prevInputValue: this.props.inputValue});
    };

    appendDelimitedValues = async (
        values: string,
        delimiter: RegExp = pasteDelimiter,
        inputCleanupDelimiter: RegExp = delimiter,
    ): Promise<number> => {
        const existingValues = this.formatValuesForCreatable();
        const entries = [...new Set(values.split(delimiter).map((e) => e.trim()))];

        if (entries.length === 0) {
            return 0;
        }

        const isUniqueEmail = (values: Array<UserProfile | EmailInvite>, email: string): boolean => {
            return values.findIndex((v) => (
                this.isEmailInvite(v) && v.value === email) || (this.isUserProfile(v) && v.email === email),
            ) === -1;
        };

        const handleEmail = async (email: string): Promise<UserProfile | string | null> => {
            if (!isUniqueEmail(existingValues, email)) {
                return null;
            }
            const resp = await this.searchByEmail(email);
            return resp || email;
        };

        const isUniqueUsername = (values: Array<UserProfile | EmailInvite>, username: string): boolean => {
            return values.findIndex((v) => this.isUserProfile(v) && v.username === username) === -1;
        };

        const handleUsername = async (username: string): Promise<UserProfile | null> => {
            if (!isUniqueUsername(existingValues, username)) {
                return null;
            }
            return this.searchByUsername(username);
        };

        const promises = entries.map(async (entry) => {
            if (entry === '') {
                return Promise.resolve(null);
            }

            let res;
            if (this.props.emailInvitationsEnabled && isEmail(entry)) {
                res = await handleEmail(entry);
            } else {
                res = await handleUsername(entry);
            }

            if (typeof res === 'string') {
                return Promise.resolve({value: res, label: res});
            } else if (this.isUserProfile(res as UserProfile)) {
                return Promise.resolve(res);
            }
            return Promise.resolve(null);
        });

        const newValues: Array<UserProfile | EmailInvite> = [];

        (await Promise.allSettled(promises)).reduce((acc, v) => {
            if (v.status === 'fulfilled') {
                acc.push(v.value);
            }
            return acc;
        }, [] as Array<UserProfile | EmailInvite | null>).forEach((v) => {
            if (!v) {
                return;
            }

            if (this.isEmailInvite(v) && (!isUniqueEmail(existingValues, v.value) || !isUniqueEmail(newValues, v.value))) {
                return;
            }

            if (this.isUserProfile(v) && (
                !isUniqueUsername(existingValues, v.username) || !isUniqueEmail(existingValues, v.email) ||
                !isUniqueUsername(newValues, v.username) || !isUniqueEmail(newValues, v.email)
            )) {
                return;
            }

            newValues.push(v);
        });

        this.onChange([...existingValues, ...newValues]);

        const unresolvedEntries = entries.filter((entry) => {
            if (!entry) {
                return false;
            }

            const cleanedEntry = entry.replace(inputCleanupDelimiter, ' ').trim();
            if (!cleanedEntry) {
                return false;
            }

            return !newValues.some((value) => {
                if (this.isEmailInvite(value)) {
                    return value.value === cleanedEntry;
                }
                return value.username === cleanedEntry || value.email === cleanedEntry;
            });
        });

        this.props.onInputChange(unresolvedEntries.join(' '));

        return newValues.length;
    };

    isUserProfile = (obj: UserProfile | EmailInvite): obj is UserProfile => {
        return (obj as UserProfile).id !== undefined;
    };

    isEmailInvite = (obj: UserProfile | EmailInvite): obj is EmailInvite => {
        return (obj as EmailInvite).value !== undefined;
    };

    searchByEmail = async (value: string): Promise<UserProfile | null> => {
        let data;
        try {
            data = await Client4.getUserByEmail(value);
        } catch {
            return null;
        }
        return data?.delete_at === 0 ? data : null;
    };

    searchByUsername = async (value: string): Promise<UserProfile | null> => {
        let data;
        try {
            data = await Client4.getUserByUsername(value);
        } catch {
            return null;
        }
        return data?.delete_at === 0 ? data : null;
    };

    render() {
        const values = this.formatValuesForCreatable();

        const Msg: any = components.NoOptionsMessage;

        const styles = {
            placeholder: (css) => ({
                ...css,

                pointerEvents: 'none',
                userSelect: 'none',
            }),
            input: (css) => ({
                ...css,

                gridTemplateColumns: '0 minmax(0, 1fr)',

                input: {
                    textAlign: 'left',
                },
            }),
            valueContainer: (css) => ({
                ...css,
                gridTemplateColumns: 'minmax(0, 1fr)',
            }),
        } satisfies StylesConfig<UserProfile | EmailInvite, true >;

        return (
            <>
                <AsyncCreatable
                    ref={this.selectRef}
                    onChange={this.onChange}
                    loadOptions={this.optionsLoader}
                    isValidNewOption={this.showAddEmail}
                    isMulti={true}
                    isClearable={false}
                    className={classNames(
                        'UsersEmailsInput',
                        this.props.showError ? 'error' : '',
                        {empty: this.props.inputValue === ''},
                        {'no-selections': values.length === 0},
                    )}
                    classNamePrefix='users-emails-input'
                    placeholder={this.props.placeholder}
                    components={this.components}
                    getOptionValue={this.getOptionValue}
                    formatOptionLabel={this.formatOptionLabel}
                    defaultOptions={false}
                    defaultMenuIsOpen={false}
                    openMenuOnClick={false}
                    loadingMessage={this.loadingMessage}
                    onInputChange={this.handleInputChange}
                    inputValue={this.props.inputValue}
                    openMenuOnFocus={true}
                    onFocus={this.onFocus}
                    tabSelectsValue={true}
                    value={values}
                    aria-label={this.props.ariaLabel}
                    autoFocus={this.props.autoFocus}
                    styles={styles}
                />
                {this.props.showError && (
                    <div className='InputErrorBox'>
                        <Msg>
                            <FormattedMarkdownMessage
                                {...this.props.errorMessage}
                                values={this.props.errorMessageValues}
                                disableLinks={true}
                            />
                        </Msg>
                        {this.props.extraErrorText || null}
                    </div>
                )}
            </>
        );
    }
}

export default injectIntl(UsersEmailsInput);
